theme.css:
/* theme: Amber Ledger | A tense summit and a volatile market day, recorded in hard-edged amber and slate on a heavy paper stock. */
/* mood: tense */
/* layout: hero=classic; major-events=timeline/stack; political-news=numbered/grid-2; financial-news=stat/stack; tech-news=outline/grid-2; entertainment-news=plain/stack; sports=split/masonry; music-releases=plain/stack; stock-analysis=stat/grid-3; outlook=tile/grid-2 */

.diary-page {
  --paper: #fbf0d9;
  --paper-alt: #f3e3c3;
  --ink: #1f1610;
  --ink-soft: #3d3227;
  --muted: #6b5a3f;
  --accent: #8f4000;
  --accent-ink: #fff7e8;
  --rule: #d4b67c;
  --font-display: var(--ff-syne), sans-serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-space-grotesk), sans-serif;

  background: var(--paper);
  color: var(--ink-soft);
}

.diary-page .diary-hero {
  background: var(--paper-alt);
  border-bottom: 3px double var(--accent);
}

.diary-page .diary-hero-inner {
  padding-top: 2.5rem;
}

.diary-page .diary-kicker {
  font-size: 0.9rem;
  letter-spacing: 0.28em;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--accent);
}

.diary-page .diary-kicker::before {
  content: "■ ";
  font-size: 0.6em;
  vertical-align: middle;
}

.diary-page .diary-title {
  font-weight: 800;
  letter-spacing: -0.02em;
  text-transform: uppercase;
  font-size: clamp(2.25rem, 5vw, 4.5rem);
  line-height: 1.05;
  color: var(--ink);
  max-width: none;
}

.diary-page .diary-summary {
  font-size: 1.2rem;
  line-height: 1.6;
  max-width: 46rem;
  border-left: 4px solid var(--accent);
  padding-left: 1.5rem;
}

.diary-page .diary-theme-note {
  font-size: 0.9rem;
  letter-spacing: 0.05em;
  color: var(--muted);
}

.diary-page .diary-theme-name {
  background: var(--accent);
  color: var(--accent-ink);
  border-radius: 0;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.diary-page .diary-toc {
  background: var(--paper);
  border-bottom: 2px solid var(--accent);
}

.diary-page .diary-toc-link,
.diary-page .diary-toc-top,
.diary-page .diary-toc-bottom {
  font-weight: 600;
  letter-spacing: 0.02em;
}

.diary-page .diary-toc-link.is-active {
  color: var(--accent);
}

.diary-page .diary-toc-number {
  color: var(--accent);
  font-weight: 700;
}

.diary-page .diary-section {
  border-top: 2px solid var(--rule);
}

.diary-page .diary-section-head {
  border-left: 6px solid var(--accent);
  padding-left: 1rem;
  margin-bottom: 2rem;
}

.diary-page .diary-section-number {
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: 0.2em;
  color: var(--accent);
}

.diary-page .diary-section-title {
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.01em;
  font-size: clamp(1.8rem, 3vw, 2.5rem);
}

.diary-page .diary-card-title {
  font-weight: 700;
  letter-spacing: -0.01em;
}

.diary-page .diary-card-thread {
  border-radius: 0;
  border: 2px solid var(--accent);
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-size: 0.7rem;
}

.diary-page .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

.diary-page .diary-prose {
  font-size: 1.1rem;
  line-height: 1.72;
}

.diary-page .diary-prose a {
  border-bottom: 2px solid var(--accent);
  font-weight: 700;
  letter-spacing: 0.08em;
}

.diary-page .diary-prose a:hover {
  color: var(--accent);
  border-bottom-color: var(--accent);
}

.diary-page .diary-prose h4 {
  font-family: var(--font-display);
  font-weight: 700;
}

.diary-page .diary-prose blockquote {
  border-left: 3px solid var(--accent);
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
}

.diary-page .diary-prose ol > li::marker {
  color: var(--accent);
}

.diary-page .diary-section:first-child .diary-card--plain:first-child .diary-prose > p:first-of-type::first-letter {
  font-weight: 700;
  color: var(--accent);
}

.diary-page .diary-stories--stack {
  max-width: 46rem;
}

.diary-page .diary-card--timeline .diary-card-inner::before {
  background: var(--rule);
  width: 3px;
}

.diary-page .diary-card--timeline .diary-card-inner::after {
  background: var(--accent);
  box-shadow: 0 0 0 4px var(--paper);
  border-radius: 0;
  width: 0.9rem;
  height: 0.9rem;
}

.diary-page .diary-card--numbered .diary-card-index {
  font-weight: 800;
  letter-spacing: -0.05em;
  font-size: 3.5rem;
}

.diary-page .diary-card--numbered .diary-card-inner {
  border-left: 3px solid var(--accent);
  padding-left: 1rem;
}

.diary-page .diary-card--stat .diary-card-inner {
  border-top: 4px solid var(--accent);
}

.diary-page .diary-card-figure {
  font-weight: 800;
  letter-spacing: -0.03em;
  color: var(--accent);
}

.diary-page .diary-card--outline .diary-card-inner {
  border: 2px solid var(--accent);
  border-radius: 0;
  padding: 1.25rem;
}

.diary-page .diary-card--outline .diary-card-inner::before {
  content: "";
  display: block;
  height: 4px;
  background: var(--accent);
  margin-bottom: 0.75rem;
  width: 3rem;
}

.diary-page .diary-card--split .diary-card-inner {
  border-top: 4px solid var(--accent);
}

.diary-page .diary-card-lede {
  border-left: 4px solid var(--accent);
  font-family: var(--font-display);
  font-weight: 400;
  font-style: italic;
}

.diary-page .diary-card--tile .diary-card-inner {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
  padding: 1.25rem;
}

.diary-page .diary-markets {
  gap: 0.5rem;
}

.diary-page .diary-spark {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
  border-left: 3px solid var(--accent);
}

.diary-page .diary-spark-line {
  color: var(--accent);
}

.diary-page .diary-spark.is-down {
  color: var(--accent);
}

.diary-page .diary-footer {
  border-top: 3px double var(--accent);
}

.diary-page .diary-footer a {
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  font-size: 0.8rem;
}

@media (min-width: 1024px) {
  .diary-page .diary-toc-link {
    border-left: 2px solid transparent;
  }

  .diary-page .diary-toc-link.is-active {
    border-left-color: var(--accent);
    font-weight: 700;
  }
}

@media (min-width: 54rem) {
  .diary-page .diary-stories--grid-3 {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .diary-page .diary-card--stat .diary-card-inner {
    display: flex;
    flex-direction: column;
  }
}

@media (max-width: 40rem) {
  .diary-page .diary-title {
    font-size: 2.25rem;
  }

  .diary-page .diary-card--numbered .diary-card-index {
    font-size: 2.75rem;
  }
}

.diary-page .diary-stories--masonry > .diary-card--split:nth-child(odd) .diary-card-inner {
  background: var(--paper-alt);
  padding: 1rem;
}

.diary-page .diary-card--split .diary-card-inner {
  padding-top: 0;
}

.diary-page .diary-card--split .diary-card-inner::before {
  content: "";
  display: block;
  height: 4px;
  background: var(--accent);
  width: 100%;
  margin-bottom: 0.75rem;
}

.diary-page .diary-card--split .diary-card-title {
  font-size: 1.3rem;
}

@media (min-width: 34rem) {
  .diary-page .diary-card--split .diary-card-inner {
    grid-template-columns: minmax(9rem, 28%) minmax(0, 1fr);
  }
}

.diary-page .diary-card--timeline .diary-card-title {
  font-size: 1.2rem;
}

.diary-page .diary-card--timeline .diary-card-body {
  font-size: 1rem;
}

.diary-page .diary-section[data-section="financial-news"] .diary-card--stat .diary-card-figure {
  font-size: clamp(2.5rem, 14cqi, 4rem);
}

.diary-page .diary-section[data-section="stock-analysis"] .diary-card--stat {
  border: 2px solid var(--rule);
  padding: 0.25rem;
}

.diary-page .diary-section[data-section="stock-analysis"] .diary-card--stat .diary-card-inner {
  border-top: 0;
  background: var(--paper);
  padding: 1rem;
  border-left: 4px solid var(--accent);
}

.diary-page .diary-section[data-section="outlook"] .diary-card--tile .diary-card-inner {
  border-left: 4px solid var(--accent);
  border-right: 0;
}

.diary-page .diary-section[data-section="entertainment-news"] .diary-card--plain .diary-card-body {
  font-size: 1.1rem;
}

.diary-page .diary-section[data-section="music-releases"] .diary-card--plain {
  padding-bottom: 1.5rem;
  border-bottom: 1px solid var(--rule);
}

.diary-page .diary-section[data-section="music-releases"] .diary-card--plain:last-child {
  border-bottom: 0;
}

.diary-page .diary-card--plain .diary-card-title {
  font-size: 1.4rem;
  position: relative;
  padding-bottom: 0.25rem;
}

.diary-page .diary-card--plain .diary-card-title::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: 0;
  width: 2.5rem;
  height: 2px;
  background: var(--accent);
}

.diary-page .diary-card--plain .diary-card-body {
  margin-top: 0.5rem;
}

.diary-page .diary-prose strong {
  color: var(--accent);
  font-weight: 700;
}

.diary-page .diary-prose em {
  color: var(--ink);
}

.diary-page .diary-card-thread {
  align-self: flex-start;
  margin-top: 0.25rem;
}

.diary-page .diary-card--timeline .diary-card-thread {
  margin-left: 0;
}

.diary-page .diary-spark.is-up .diary-spark-change {
  color: var(--accent);
}

.diary-page .diary-spark.is-down .diary-spark-change {
  color: var(--accent);
}

.diary-page .diary-footer-meta {
  letter-spacing: 0.05em;
}

.diary-page .diary-prose ::selection {
  background: var(--accent);
  color: var(--accent-ink);
}
